const body = $input.first().json.body || {};

// 参数校验与默认值
const provider = body.provider || 'agnes';
const prompt = body.prompt;
const size = body.size || '1024x1024';
const n = body.n || 1;

if (!prompt) {
  throw new Error('缺少必填字段: prompt (图片生成提示词)');
}

// 支持的 provider
const supportedProviders = ['agnes'];
if (!supportedProviders.includes(provider)) {
  throw new Error(`不支持的 provider: ${provider}。当前支持: ${supportedProviders.join(', ')}`);
}

// 构建 Agnes AI 请求
const requestBody = {
  provider: provider,
  request: {
    model: 'agnes-image-2.1-flash',
    prompt: prompt,
    size: size,
    n: n
  },
  metadata: {
    provider: provider,
    prompt: prompt,
    size: size,
    requestedAt: new Date().toISOString()
  }
};

return [{ json: requestBody }];

const response = $input.first().json;

if (response.error) {
  throw new Error('Agnes AI 返回错误: ' + JSON.stringify(response.error).substring(0, 500));
}

const imageData = response.data;
if (!imageData || !imageData[0] || !imageData[0].url) {
  throw new Error('未找到图片 URL: ' + JSON.stringify(response).substring(0, 500));
}

return [{ json: { imageUrl: imageData[0].url } }];

const item = $input.first();

const hasBinary = !!(item.binary && item.binary.data);

if (!hasBinary) {
  return [{
    json: {
      success: false,
      error: '图片下载失败',
      provider: 'agnes'
    }
  }];
}

const binaryData = item.binary.data;

return [{
  json: {
    success: true,
    provider: 'agnes',
    model: 'agnes-image-2.1-flash',
    fileName: binaryData.fileName || `image_${Date.now()}.png`,
    mimeType: binaryData.mimeType || 'image/png',
    fileSize: binaryData.fileSize || 0,
    generatedAt: new Date().toISOString()
  },
  binary: { data: binaryData }
}];
